import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"周易集说卷二","description":"周易集说 - 周易集说卷二","frontmatter":{"title":"周易集说卷二","description":"周易集说 - 周易集说卷二"},"headers":[],"relativePath":"zh/classics/jishuo/003.md","filePath":"zh/classics/jishuo/003.md"}'),r={name:"zh/classics/jishuo/003.md"};function i(o,p,c,_,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="周易集说卷二" tabindex="-1">周易集说卷二 <a class="header-anchor" href="#周易集说卷二" aria-label="Permalink to “周易集说卷二”">​</a></h1><p>钦定四库全书</p><p>宋俞琰撰</p><p>䷅ 坎下乾上</p><p>「讼」：有孚窒惕，中吉，终凶。利见大人，不利涉大川。</p><p>「讼」，争辩也。「上」，「乾」刚，下，「坎」险，又为内险外健，皆讼之道也。九二为成卦之主爻。「有孚窒惕，中吉，终凶」，皆指九二。「有孚窒惕」，谓九二虽与九五同德相孚，然为二阴所陷，而曲直未判，则此心未免窒塞而不通，惕惧而不自安也。「中吉」，谓刚而得中，所以「吉」也。「终凶」，谓讼不可成，要其终则虽胜亦凶。「大人」，指九五。「利见」，谓占者讼而有理，则宜见之也。坎水之险在下，「乾」以刚乘险，以实履陷，故其象占又为「不利涉大川」。</p><p>初六：不永所事，小有言，终吉。</p><p>初六以阴柔处讼之初，才弱位卑，而为讼不成，故不言「讼」，而曰「不永所事，小有言，终吉」。夫彖辞言「终凶」，爻辞乃言「终吉」，何也？曰：彖为讼者言，爻为不讼者言也。</p><p>九二，不克讼，归而逋，其邑人三百户，无眚。</p><p>九二以刚居柔，故「不克讼」。「逋」，逃也。与五不相应，遂归而逋。既「逋」，则近己者皆无连坐之患，故曰：「其邑人三百户，无眚。」</p><p>六三，食旧德，贞厉，终吉；或从王事，无成。</p><p>六三柔而不讼，故不言「讼」。「食」，犹食邑之「食」，言所享也。讼六三之「贞」，即「坤」六三之「贞」，故称「旧德」。其位虽处九二刚阳之上而危厉，然以贞道自守而不讼，亦「终吉」也，故曰：「食旧德，贞厉，终吉。」「王」指五。「或从王事，无成」，与「坤」之六三同，是亦「旧德」也。彼言「或从王事，无成」，又言「有终」；此但言「或从王事，无成」，而不言「有终」，何也？曰：彼顺而此险也，险非善后之道也。</p><p>九四，不克讼，复即命，渝，安贞吉。</p><p>九四以刚居柔，故亦「不克讼」。「即」，就也。「渝」，变也。郑国风羔裘诗云：「舍命不渝。」大雅板诗云：「敬天之渝。」皆训「变」。讼非善事，四也舍其不善以复其善，遂听命于五，而渝变前日之所为，安守今日之正理，故「吉」。九五：讼，元吉。</p><p>九五以刚明之德居尊而又中正，彖辞所谓「大人」是也。「讼」之有理者，见之必𫉬伸矣。「元吉」，乃吉之尽善者也。盖其始焉本吉，非若九四转凶而为吉也。</p><p>上九：或锡之鞶带，终朝三褫之。「鞶带」，大带也，所以束身而用其恭也。上九终极其讼，徼幸取胜，故或有鞶带之锡。「锡之」，所以愧之也。「鞶带」，指三。「锡之」者，五也。三与上相应，盖与之从事于王所者也。三不有其成，上乃得受此锡。「褫」，解也。「终朝三褫之」，愧可知矣。三，去声。䷆ 坎下坤上 师，贞，丈人吉，无咎。</p><p>师，兵众也。贞，正也。此卦下坎上坤，动众行险而以顺，师之正也。丈人，当如困彖辞作大人，指九二，阳德之大也。刚中而有应，众阴皆顺从之，故「吉」而「无咎」。</p><p>初六，师出以律，否臧，凶。</p><p>在师之初，故曰「师出律」，言其和。否，方九反。否臧，不善也。春秋左氏传云：「师克在和，不在众。」今以六归初，柔邪而不中，焉得和？不和则不善，丧师之道也，故曰：「否臧，凶」。按周礼：「太师执同律以听军声。」盖古者出师必吹律，律和则知士卒同心，犹后世军中风角鸟占也。九二，在师中，吉，无咎，王三锡命。</p><p>在师之中，为成卦之主，故以彖辞「吉无咎」属之。所以「吉」而「无咎」者，有应于上，而六五之君宠任之专也。刚中而无过，故为三承王命之奖谕。王，指五。三，去声。六三，师或舆尸，凶。</p><p>或，疑辞。行师而用人不一，则众有疑二之心也。舆，与文子「舆死扶伤」之「舆」同。尸，与春秋左氏传「秦封殽尸」、「楚收晋尸」之尸同。舆尸，谓师徒挠败，舆载其尸而归也。六三半动半静，柔邪而不中，故其「凶」如此。六四：师左次，无咎。</p><p>左次，退舍而处于僻左之地也。按春秋庄公八年：「师次于郎，以俟陈人、蔡人。」「次」，谓止而不进也。易以阳为右，阴为左。六四爻位俱阴，故称「左」。才志柔弱，虽不能成进取之功，然居得其正，而能完师以退，故亦「无咎」。</p><p>六五：田有禽，利执言，无咎。长子帅师，弟子舆尸，贞凶。下有二应，是为「田有禽」。言当依郭京作之。「畋于田」，所以去害稼之物，执之则利，故「无咎」。师至五，乃师旋论功之时，故言「长子」、「弟子」之得失。「长子」，指九二。「弟子」，指六三。六三柔而不中，其可使哉？必固使之，故有「舆尸」之凶，是谁之过欤？「贞」，谓六五固执而不知变也。</p><p>上六：大君有命，开国承家，小人勿用。</p><p>师至上，乃定功行赏之时，故言「大君有命，开国承家」。「君」，指六五。以阴柔之小，下从九二阳刚之大，故称「大」。「开国」，谓封为诸侯。「承家」，谓传之子孙而世袭其爵。「小人勿用」，谓小人得此占，则不宜动而用事也。䷇ 坤下坎上</p><p>「比」，吉。原筮，元永贞，无咎。不宁方来，后夫凶。</p><p>「比」，相亲也。九五以一阳居尊，而众阴在下，皆「比」之，故「吉」。「原」，再也。礼之「原庙」、「原蚕」，春秋左氏传之「原田」，皆训再。初筮得「坤」，再筮得「坎」。九五乃为成卦之主，刚得中而「元永贞」，故「无咎」。「坎」，劳卦，是为不宁。谓六四辅己而不惮其劳也。「来」，谓在下三阴之顺从也。「坎」为加忧，「坤」阴多疑。师旋之后，天下归附方新，上下忧疑未定，四也不遑宁处，以五之意达于初、二、三，又以初、二、三之意达于五，然后上下相应，而初、二、三乃始顺从而来比也。上处外，独后于五，是为「后夫」。不得其「比」，故「凶」。</p><p>初六：有孚比之，无咎。有孚盈缶，终来有它，吉。</p><p>此爻凡两言「有孚」，当分为两说。始言「有孚」，孚于四也。次言「有孚」，孚于二也。四乃五之近臣，初与之比，固亦「无咎」；二与五乃君臣正应，初与二比，则可因二以比五，此则「吉」之道也。「缶」指二，虚而能受，故象「缶」。「盈之」者，五也，谓二五相比之深，如水之盈缶也。始者二往比五，终则五来应二，故曰「终来」。二非初之正应，故言「它」。</p><p>六二，比之自内，贞吉。</p><p>五为比主，二应五而自内比之，则无假于它，故言自贞吉。谓六二能固守以正，不比三而比五，则吉也。六三，比之匪人。</p><p>「匪」，非也。「比」上六之「后夫」，则所比非其人矣。六四，外比之，贞吉。</p><p>二在内而应五，故曰「比之自内」；四在外而承五，故曰「外比之」。二、四皆守正而不与三比，故其占皆曰「贞吉」。</p><p>九五，显比，王用三驱，失前禽，邑人不诫，吉。</p><p>九五以刚明中正之德居尊，至公无私，而下皆顺从，故曰「显比」。师二至五，比五至二，皆历三爻，故师言「三锡」，比言「三驱」。「王用三驱失前禽」，犹王制「天子不合围」之义。禽既去则不追，故曰「失前禽」。「前禽」，即「后夫」。众已比五，而上独后至，是为「后夫」。众皆随五，而上独前去，是为「前禽」。「邑人」指二。「诫」者，戒其不妄杀也。是时下皆顺从，而邑人盖知上意，故不待诫。凡此皆吉之道也。上六：比之无首，凶。</p><p>「比」道贵先，而上六独为「后夫」，「比之无首」者也，故「凶」。䷈ 乾下巽上</p><p>小畜，亨。</p><p>密云不雨，自我西郊。</p><p>释文云：畜，本作蓄，𠡠六反。六四以阴柔之小，为成卦之主，而才力单弱，包蓄三阳不住，是为「小畜」。内健而外巽，四与五又相孚，故「亨」。「云」，阴气。「西郊」，阴方。阳倡阴和，则阴阳和洽而为雨。阴先阳倡，则阴阳不和而「无雨」。今也云虽密而「不雨」，盖「自我西郊」故也。「我」与「西郊」，皆指四。在下三阳皆不顺从，故其象如此。</p><p>初九：复自道，何其咎，吉。</p><p>复，谓返于本位也。以初九之刚，往应六四之柔，而受其制，岂不失其道而有咎？今也返而以正道自守，故能转咎而为吉。九二，牵复，吉。</p><p>与初九相牵连而复，故「吉」。</p><p>九三，舆说辐，夫妻反目。</p><p>辐，当如大畜九二作「輹」，车下横缚也。说，音脱。辐，指二；舆，三自谓也。二牵初而复，则三之舆说其輹而不行矣。九三与六四，阴阳相并，夫妻之象也。阳不受制于阴，则其情不和，故曰「夫妻反目」。六四，有孚，血去惕出，无咎。</p><p>四与五相孚，而位据群刚之上，不能无争，争则必伤。而言「血去」者，六四柔顺而正，虽与五合志，不挟势以陵下，盖无争也。无争则无伤，况又惕然而惧，释位而出，则亦无咎矣。其义与需六四同。</p><p>九五，有孚挛如，富以其邻。</p><p>五与四相孚，亲密而固结之甚，故曰「挛如」。易以阳实为富，九五阳爻，故曰「富」。「富以其邻」，谓九五之所以富，盖能任用六四，并力以畜乾也。</p><p>上九，既雨既处，尚德载，妇贞厉，月几望，君子征凶。彖辞云「密云不雨」，谓阴阳不和也。爻至上九畜极，则倒转为履。乾上兑下，其泽自天而降。昔之不雨者，今「既雨」矣。雨则和，和则止，故曰「既雨既处」。处，上声。尚德载，「妇贞厉，月几望」，皆指六四。阴之所尚，宜处下以德载物。今也三阳在下，而六四高据其上，岂所宜哉？倒转为履之六三而居下，则顺承三阳而为载，乃所宜也。阴畜阳，犹妇畜其夫。畜道既极，犹固执而不知变，则危矣，故曰「妇贞厉」。几，音机，近也。月与日正相对为「望」。「几望」，谓将望而光未盈也。能以危厉为戒，而不自满假，则如月之几望也。君子，指占者而言。以正道而行谓之「征」。君子得此占，虽以正道而行，亦宜处静而不宜动。下无应援，动将何之？动则凶也。䷉ 兑下乾上 履虎尾，不咥人，亨。「履虎尾」，谓乾刚在前，兑柔自后蹑之也。乾虽刚猛如虎，兑以和说应之，则不至见害，故曰「不咥人」。咥，直结反，啮也。占者所履如此，亨之道也。初九，素履，往，无咎。</p><p>履道贵柔不贵刚。在履之初，而以刚居刚，本亦有咎。唯能安于素履，处卑下而不僭，则其往也无咎。</p><p>九二，履道坦坦，幽人贞吉。</p><p>九二以刚居柔而得中，履道之坦坦者也。处静守贞，内安恬退而不自乱，故其象为「幽人」，其占曰「贞吉」。</p><p>六三，眇能视，跛能履，履虎尾，咥人，凶；武人为于大君。视欲其正，而六三不正，眇也，虽能视，不足以有明也。行欲其中，而六三不中，跛也，虽能履，不足以有行也。彖辞言「履虎尾」，此亦言「履虎尾」。六三乃成卦之主爻也。彖辞言「不咥人」，此乃言「咥人凶」。彖自彖义，爻自爻义也。六三不中不正，又以柔居刚，动则遇害，故为咥人之凶。武人得此占，则见危授命，奋不顾身，可以有为而进用于大君也。大君，指九五而言。</p><p>九四，履虎尾，诉诉，终吉。</p><p>乾之刚猛如虎，上九其首，九四正尾也，故亦曰「履虎尾」。诉，所革反。诉诉，惊貌。九四虽不中不正，然以刚居柔，履危而知惧，故其占为始虽甚危，其终则吉。九五：夬履，贞厉。</p><p>履以和行，而九五下无正应，唯以刚明自任。凡事决而不和，又固执而不知变，危厉之道也。上九：视履，考祥，其旋，元吉。</p><p>「视履」为句。「考祥其旋」为句。祥，当依荀爽作「详」。初居履之始，故言「往」。上居履之终，故言「旋」。昔往而今旋也。能自视所履，而加考察之功，详审其旋，不失其素，而终始如一，则「元吉」。不然，何「元吉」之有？䷊ 乾下坤上</p><p>泰，小往大来，吉，亨。</p><p>「泰」者，天地交而上下相通之时也。「小往」，谓阴往居外。大来，谓阳来居内。内君子而外小人，故其占曰「吉亨」。</p><p>初九：拔茅茹以其汇，征吉。</p><p>「茅茹」，茅之根也。汇，音谓，类也。初进则二、三俱进，犹茅根牵连，拔则俱起，故其象为「拔茅茹以其汇」，而其占为「征行」之「吉」。</p><p>九二：包荒，用冯河，不遐遗。朋亡，得尚乎中行。</p><p>「荒」，与书说命「荒野」之「荒」同。初九在下，刚而不中，荒野草茅之士也。九二包容之，故曰「包荒」。若九三则非但刚而不中，又处健体之极，徒步涉河，死而无悔者也。九二亦用之，故曰「用冯河」。冯，音凭。诗小旻云：「无敢冯河。」毛氏注云：「冯，陵也。」三阴在外，虽远九二，亦不弃之，故曰「不遐遗」。「朋」，谓「坤」之朋，六四、上六是也。「中行」，指五。「尚」，配也。五交于二，则五也丧其坤朋，而二也得尚乎五，故曰：「朋亡，得尚于中行。」向使六五不朋亡，而唯与六四、上六为党，则二欲上交于五，其可得乎？</p><p>九三，无平不陂，无往不复，艰贞无咎。勿恤其孚，于食有福。</p><p>陂，彼伪反。有平则有陂，有往则有复，无有久平而不陂，久往而不复者。三处泰道方中之时，亦未至乎极。圣人居安虑危，故为此戒。艰则操心也危，而不敢慢易；「贞」则守德也固，而不敢放纵。如此则无过咎，而彼之孚可以勿忧，我之福可以自享。盖在我者，礼义不愆，则自治有余，何用它恤？</p><p>六四，翩翩，不富以其邻，不戒以孚。「翩翩」，降以相从之貌。易以阴虚为不富，六四阴爻，故曰「不富」。四当小人道消之时，所以翩翩然下交于初者，其心自歉其不富，遂以其邻偕来也。「戒」，备也。「戒」而「孚」，则非其愿；「不戒以孚」，则其中心愿也。「泰」之时，上下交而其志同，君子小人两不相疑，又何戒备之有？三阳以其汇交于上，故三阴亦以其邻交于下。三交于上，勿恤其孚，故四交于下，亦不戒以孚。</p><p>六五，帝乙归妹，以祉，元吉。六五以阴柔居尊，下应九二，为「帝乙归妹」之象。「祉」，禄也。「以祉」，以禄及下也。以二视五，则自下而尚于五；以五视二，则自上而归于二。上下相交，吉之尽善者也。卦互「归妹」，故其象占如此。</p><p>上六，城复于隍，勿用师，自邑告命，贞吝。</p><p>「隍」，城下堑。城以积土而成，「圯」则土复归隍。「泰」极则倒转为「否」，故其象如此。其占曰「勿用」，谓不可动而用事也。是时城圮隍塞，自治且不暇，何暇兴师动众以治人也哉？「师」，众也。「邑」，都邑，国之内也。师「自邑告命」，则征伐自大夫出也。泰之三阴本在外以听命于内者，倒转为否，则三阴乃居内以制其外向也。内君子外小人，至此则内小人外君子，君子反听命于小人也。「贞吝」，戒占者固执而不识时势，则有甚可羞吝也。周易集说卷二，</p>',68)])])}const m=a(r,[["render",i]]);export{h as __pageData,m as default};
